const fastify = require('fastify')({ logger: true });
const multipart = require('@fastify/multipart');
const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

fastify.register(multipart);

fastify.post('/create-gif', async (req, reply) => {
  const data = await req.file();
  const fields = await data.fields();

  const images = fields.images;
  const targetSize = fields.targetSize.value;
  const delay = fields.delay ? parseInt(fields.delay.value, 10) : 10;
  const appendReverted = fields.appendReverted ? fields.appendReverted.value === 'true' : false;

  if (!images || !targetSize) {
    return reply.status(400).send({ error: 'images and targetSize are required fields' });
  }

  const imageFiles = [];
  try {
    for await (const part of images) {
      const filePath = path.join(__dirname, 'uploads', `${uuidv4()}-${part.filename}`);
      await part.toFile(filePath);
      imageFiles.push(filePath);
    }

    const gifPath = path.join(__dirname, 'uploads', `${uuidv4()}.gif`);
    const imagePaths = imageFiles.join(' ');

    let command = `convert -delay ${delay} -resize ${targetSize} ${imagePaths}`;

    if (appendReverted) {
      const reversedPaths = imageFiles.reverse().join(' ');
      command += ` ${reversedPaths}`;
    }

    command += ` ${gifPath}`;

    exec(command, (error) => {
      if (error) {
        return reply.status(500).send({ error: 'Failed to create GIF' });
      }

      reply.type('image/gif').send(fs.createReadStream(gifPath));

      // Clean up temporary files
      imageFiles.forEach(file => fs.unlinkSync(file));
      fs.unlinkSync(gifPath);
    });
  } catch (err) {
    return reply.status(500).send({ error: 'Internal Server Error' });
  }
});

const start = async () => {
  try {
    await fastify.listen({ port: 5000, host: '0.0.0.0' });
    fastify.log.info(`Server listening on http://0.0.0.0:5000`);
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
};

start();
</CODE>
